 "Cuéntalo": "Parles-en",
 "<b style=\"font-size:28px;color:#3c78a8\">Cuéntalo</b><br><span style=\"font-size:23px;color:#1f2a22\">A una persona adulta de confianza.</span>": "<b style=\"font-size:28px;color:#3c78a8\">Parles-en</b><br><span style=\"font-size:23px;color:#1f2a22\">À un adulte de confiance.</span>",
